import * as THREE from "three";
import { store } from "../core/store";

/*
 * A procedural Earth and Moon. Nothing is downloaded: continents, biomes, clouds, city lights,
 * aurora and lunar craters are all generated by shaders. It is a stylised model for the game, not
 * real satellite imagery, and the on-screen caption says so.
 */

const NOISE = /* glsl */ `
  float hash3(vec3 p) { p = fract(p * 0.3183099 + 0.1); p *= 17.0; return fract(p.x * p.y * p.z * (p.x + p.y + p.z)); }
  float noise3(vec3 x) {
    vec3 i = floor(x), f = fract(x);
    f = f * f * (3.0 - 2.0 * f);
    return mix(
      mix(mix(hash3(i), hash3(i + vec3(1, 0, 0)), f.x), mix(hash3(i + vec3(0, 1, 0)), hash3(i + vec3(1, 1, 0)), f.x), f.y),
      mix(mix(hash3(i + vec3(0, 0, 1)), hash3(i + vec3(1, 0, 1)), f.x), mix(hash3(i + vec3(0, 1, 1)), hash3(i + vec3(1, 1, 1)), f.x), f.y),
      f.z);
  }
  float fbm3(vec3 p) { float v = 0.0, a = 0.5; for (int i = 0; i < 5; i++) { v += a * noise3(p); p *= 2.03; a *= 0.5; } return v; }
  float fbm3lo(vec3 p) { float v = 0.0, a = 0.5; for (int i = 0; i < 3; i++) { v += a * noise3(p); p *= 2.03; a *= 0.5; } return v; }
`;

const CLOUD_FN = /* glsl */ `
  float cloudAt(vec3 p, float t) {
    vec3 q = p * 2.5 + vec3(t * 0.010, 0.0, t * 0.006);
    float w = fbm3(q * 1.7 + 4.0);
    return smoothstep(0.50, 0.80, fbm3(q + w * 0.95));
  }
`;

const SPHERE_VERT = /* glsl */ `
  varying vec3 vObj;
  varying vec3 vWorldNormal;
  varying vec3 vViewDir;
  void main() {
    vObj = normalize(position);
    vec4 world = modelMatrix * vec4(position, 1.0);
    vWorldNormal = normalize(mat3(modelMatrix) * normal);
    vViewDir = normalize(cameraPosition - world.xyz);
    gl_Position = projectionMatrix * viewMatrix * world;
  }
`;

const EARTH_FRAG = /* glsl */ `
  precision highp float;
  varying vec3 vObj;
  varying vec3 vWorldNormal;
  varying vec3 vViewDir;
  uniform float uTime;
  uniform vec3 uSun;
  uniform mat3 uRot;
  ${NOISE}
  ${CLOUD_FN}
  float heightAt(vec3 p) { return fbm3(p * 1.6 + 3.1) * 0.75 + fbm3(p * 3.4 + 9.0) * 0.25; }

  void main() {
    vec3 p = normalize(vObj);
    float hgt = heightAt(p);
    float land = smoothstep(0.495, 0.512, hgt);
    float lat = abs(p.y);
    float elev = clamp((hgt - 0.51) * 3.2, 0.0, 1.0);
    float moist = fbm3(p * 2.6 + 17.0);

    // Subtropical deserts sit in two bands either side of the equator, where moist air has already rained out.
    float dry = smoothstep(0.12, 0.30, lat) * (1.0 - smoothstep(0.40, 0.58, lat)) * smoothstep(0.58, 0.40, moist);
    vec3 forest = vec3(0.035, 0.12, 0.05);
    vec3 grass = vec3(0.20, 0.27, 0.09);
    vec3 sand = vec3(0.66, 0.52, 0.32);
    vec3 rock = vec3(0.30, 0.26, 0.23);
    vec3 tundra = vec3(0.30, 0.32, 0.27);
    vec3 snow = vec3(0.93, 0.95, 1.0);
    vec3 ground = mix(forest, grass, smoothstep(0.38, 0.70, moist));
    ground = mix(ground, tundra, smoothstep(0.55, 0.75, lat));
    ground = mix(ground, sand, dry);
    ground = mix(ground, rock, smoothstep(0.30, 0.75, elev));
    ground *= 0.78 + 0.44 * noise3(p * 70.0);
    float snowAmt = smoothstep(0.80, 0.90, lat + elev * 0.08 + (fbm3(p * 6.0) - 0.5) * 0.12);
    ground = mix(ground, snow, snowAmt);

    float depth = smoothstep(0.512, 0.30, hgt);
    vec3 ocean = mix(vec3(0.03, 0.30, 0.42), vec3(0.004, 0.025, 0.11), pow(depth, 0.6));
    float ice = smoothstep(0.84, 0.93, lat + (fbm3(p * 5.0) - 0.5) * 0.1);
    ocean = mix(ocean, snow, ice);
    vec3 albedo = mix(ocean, ground, land);
    float cl = cloudAt(p, uTime);

    // Relief: small height noise tilts the surface normal so mountains catch the light.
    float e = 0.002;
    float b0 = noise3(p * 60.0);
    vec3 g = vec3(noise3((p + vec3(e, 0.0, 0.0)) * 60.0) - b0, noise3((p + vec3(0.0, e, 0.0)) * 60.0) - b0, noise3((p + vec3(0.0, 0.0, e)) * 60.0) - b0) / e;
    g -= dot(g, p) * p;
    vec3 n = normalize(vWorldNormal - (uRot * g) * 0.0042 * land * (0.25 + elev));

    vec3 L = normalize(uSun);
    vec3 V = normalize(vViewDir);
    float dN = dot(normalize(vWorldNormal), L);
    float day = smoothstep(-0.05, 0.18, dN);
    float lambert = max(dot(n, L), 0.0);
    vec3 sunCol = vec3(1.0, 0.96, 0.90);

    // Cloud shadows: the same cloud field sampled a little toward the sun, so shadows fall away from it.
    vec3 Lo = L * uRot;
    float shadow = cloudAt(p - Lo * 0.03, uTime);
    vec3 col = albedo * (0.012 + 1.18 * lambert * (1.0 - 0.42 * shadow)) * sunCol;

    // Ocean: a tight sun glint, a broad sheen and sky reflection at grazing angles.
    vec3 H = normalize(L + V);
    float nh = max(dot(n, H), 0.0);
    float water = (1.0 - land) * (1.0 - cl) * day;
    col += sunCol * (pow(nh, 320.0) * 0.7 + pow(nh, 18.0) * 0.12) * water;
    float fr = pow(1.0 - max(dot(n, V), 0.0), 4.0);
    col = mix(col, vec3(0.20, 0.36, 0.72) * (0.2 + lambert), fr * 0.45 * (1.0 - land));

    // Night side: city lights cluster in populated regions and thin out near the poles.
    float night = smoothstep(0.08, -0.20, dN);
    float pop = smoothstep(0.52, 0.74, fbm3(p * 9.0 + 2.0));
    float cityN = noise3(p * 34.0) * 0.6 + noise3(p * 70.0) * 0.4;
    float lights = smoothstep(0.62, 0.80, cityN) * pop * land * (1.0 - smoothstep(0.75, 0.90, lat)) * (1.0 - cl * 0.8);
    lights *= 0.75 + 0.25 * sin(uTime * 2.0 + p.x * 200.0);
    col += vec3(1.0, 0.72, 0.38) * lights * night * 1.7;

    // Aurora: shimmering curtains in a ring around each magnetic pole, visible on the night side.
    float ab = smoothstep(0.88, 0.92, lat) * (1.0 - smoothstep(0.95, 0.985, lat));
    float ar = ab * (0.5 + 0.5 * sin(atan(p.z, p.x) * 9.0 + uTime * 0.6 + fbm3(p * 4.0 + uTime * 0.05) * 6.0));
    col += mix(vec3(0.10, 1.0, 0.50), vec3(0.60, 0.20, 0.90), fbm3(p * 3.0)) * ar * 0.6 * night;

    // Sunset glow along the terminator, and atmospheric limb.
    float term = exp(-pow(dN / 0.16, 2.0));
    col += vec3(1.0, 0.42, 0.18) * term * 0.10;
    float rim = pow(1.0 - max(dot(n, V), 0.0), 3.0);
    vec3 atmo = mix(vec3(0.18, 0.38, 1.0), vec3(1.0, 0.5, 0.25), term);
    col += atmo * rim * 0.85 * (0.15 + 0.85 * smoothstep(-0.35, 0.45, dN));
    gl_FragColor = vec4(col, 1.0);
  }
`;

const CLOUD_FRAG = /* glsl */ `
  precision highp float;
  varying vec3 vObj;
  varying vec3 vWorldNormal;
  varying vec3 vViewDir;
  uniform float uTime;
  uniform vec3 uSun;
  ${NOISE}
  ${CLOUD_FN}
  void main() {
    vec3 p = normalize(vObj);
    float cl = cloudAt(p, uTime);
    float detail = 0.65 + 0.35 * fbm3lo(p * 11.0 + uTime * 0.01);
    float a = cl * detail * 0.92;
    if (a < 0.01) discard;
    vec3 L = normalize(uSun);
    float dN = dot(normalize(vWorldNormal), L);
    float lit = smoothstep(-0.12, 0.30, dN);
    vec3 c = mix(vec3(0.012, 0.016, 0.034), vec3(1.0, 0.98, 0.95) * (0.28 + 0.85 * max(dN, 0.0)), lit);
    c += vec3(1.0, 0.45, 0.2) * exp(-pow(dN / 0.14, 2.0)) * 0.18;
    gl_FragColor = vec4(c, a);
  }
`;

const ATMO_VERT = /* glsl */ `
  varying vec3 vNormal;
  varying vec3 vWN;
  void main() {
    vNormal = normalize(normalMatrix * normal);
    vWN = normalize(mat3(modelMatrix) * normal);
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const ATMO_FRAG = /* glsl */ `
  varying vec3 vNormal;
  varying vec3 vWN;
  uniform vec3 uSun;
  void main() {
    float i = pow(max(0.0, 0.72 - dot(vNormal, vec3(0.0, 0.0, 1.0))), 3.5);
    float s = dot(normalize(vWN), normalize(uSun));
    float lit = 0.22 + 0.78 * smoothstep(-0.35, 0.5, s);
    vec3 c = mix(vec3(0.25, 0.50, 1.0), vec3(0.95, 0.55, 0.38), exp(-pow(s / 0.25, 2.0)) * 0.7);
    gl_FragColor = vec4(c * i * 1.3 * lit, 1.0);
  }
`;

const MOON_FRAG = /* glsl */ `
  precision highp float;
  varying vec3 vObj;
  varying vec3 vWorldNormal;
  varying vec3 vViewDir;
  uniform vec3 uSun;
  uniform mat3 uRot;
  ${NOISE}

  // One cratered terrain layer: a bowl with a raised rim inside each cell that has a crater.
  float craters(vec3 p, float scale, float minSize) {
    vec3 q = p * scale;
    vec3 i = floor(q);
    vec3 f = fract(q);
    float h = 0.0;
    for (int x = -1; x <= 1; x++) for (int y = -1; y <= 1; y++) for (int z = -1; z <= 1; z++) {
      vec3 g = vec3(float(x), float(y), float(z));
      vec3 id = i + g;
      float size = hash3(id + 3.7);
      if (size < minSize) continue;
      vec3 o = vec3(hash3(id), hash3(id + 7.1), hash3(id + 13.3));
      float d = length(g + o - f);
      float R = 0.12 + 0.32 * size;
      float t = d / R;
      h += -smoothstep(1.0, 0.0, t) * 0.55 + smoothstep(0.78, 1.0, t) * smoothstep(1.4, 1.0, t) * 0.32;
    }
    return h;
  }
  float terrain(vec3 p) { return craters(p, 5.0, 0.30) + craters(p + 4.0, 12.0, 0.45) * 0.55 + craters(p + 9.0, 28.0, 0.60) * 0.28; }

  void main() {
    vec3 p = normalize(vObj);
    float h0 = terrain(p);
    float e = 0.01;
    vec3 g = vec3(terrain(normalize(p + vec3(e, 0.0, 0.0))) - h0, terrain(normalize(p + vec3(0.0, e, 0.0))) - h0, terrain(normalize(p + vec3(0.0, 0.0, e))) - h0) / e;
    g -= dot(g, p) * p;
    vec3 n = normalize(vWorldNormal - (uRot * g) * 0.075);

    // Dark basaltic maria fill the low, smooth plains.
    float maria = smoothstep(0.52, 0.62, fbm3(p * 1.7 + 5.0));
    vec3 highland = vec3(0.66, 0.64, 0.61);
    vec3 mare = vec3(0.20, 0.20, 0.22);
    vec3 albedo = mix(highland, mare, maria * 0.9);
    albedo *= 0.82 + 0.3 * fbm3(p * 9.0) + h0 * 0.12;

    vec3 L = normalize(uSun);
    float lam = max(dot(n, L), 0.0);
    float dN = dot(normalize(vWorldNormal), L);
    vec3 col = albedo * (0.015 + 1.15 * lam * smoothstep(-0.05, 0.2, dN + 0.05));
    // Earthshine: sunlight bounced off Earth faintly lights the dark side.
    col += albedo * vec3(0.03, 0.04, 0.08) * (1.0 - smoothstep(-0.1, 0.2, dN));
    gl_FragColor = vec4(col, 1.0);
  }
`;

const SWEEP_VERT = /* glsl */ `
  varying vec2 vP;
  void main() {
    vP = position.xy;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const SWEEP_FRAG = /* glsl */ `
  precision highp float;
  varying vec2 vP;
  uniform float uTime;
  uniform float uR;
  void main() {
    float r = length(vP) / uR;
    float a = atan(vP.y, vP.x);
    float s = mod(uTime * 0.7 - a, 6.28318) / 6.28318;
    float wedge = pow(1.0 - s, 9.0);
    float rings = (smoothstep(0.012, 0.0, abs(r - 0.34)) + smoothstep(0.012, 0.0, abs(r - 0.67)) + smoothstep(0.016, 0.0, abs(r - 0.99))) * 0.30;
    float ticks = smoothstep(0.03, 0.0, abs(fract(a * 6.0 / 3.14159) - 0.5) - 0.47) * smoothstep(0.94, 0.99, r) * 0.7;
    float fade = 1.0 - smoothstep(0.9, 1.0, r);
    float alpha = (rings + wedge * 0.20 * fade + ticks * 0.4) * step(r, 1.0);
    gl_FragColor = vec4(vec3(0.72, 0.65, 0.95) * alpha, alpha);
  }
`;

export interface Widget {
  dispose(): void;
}

export interface EarthMoonWidget extends Widget {
  /** How many craft to show on their own orbits (1 to 8). */
  setCraft(count: number): void;
}

/** Ground stations (latitude, longitude in degrees). Illustrative sites, not a real network. */
const STATIONS: [number, number][] = [
  [28.5, -80.6],
  [-35.4, 148.9],
  [40.4, -4.2],
  [-25.9, 27.7],
  [13.1, 80.3],
  [64.8, -147.5],
];

function latLon(lat: number, lon: number): THREE.Vector3 {
  const la = THREE.MathUtils.degToRad(lat);
  const lo = THREE.MathUtils.degToRad(lon);
  return new THREE.Vector3(Math.cos(la) * Math.cos(lo), Math.sin(la), -Math.cos(la) * Math.sin(lo));
}

export function createEarthMoonWidget(container: HTMLElement): EarthMoonWidget {
  const canvas = document.createElement("canvas");
  canvas.setAttribute("aria-hidden", "true");
  canvas.style.cssText = "width:100%;height:100%;display:block";
  container.append(canvas);

  const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));

  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(38, 1, 0.1, 100);
  camera.position.set(0, 0.5, 5.2);
  camera.lookAt(0, 0, 0);

  const sun = new THREE.Vector3(4, 1.5, 3).normalize();
  const earthRot = new THREE.Matrix3();
  const moonRot = new THREE.Matrix3();
  const uniforms = { uTime: { value: 0 }, uSun: { value: sun }, uRot: { value: earthRot } };

  const earth = new THREE.Mesh(new THREE.SphereGeometry(1, 128, 128), new THREE.ShaderMaterial({ vertexShader: SPHERE_VERT, fragmentShader: EARTH_FRAG, uniforms }));
  earth.rotation.z = THREE.MathUtils.degToRad(23.4);
  scene.add(earth);

  const clouds = new THREE.Mesh(
    new THREE.SphereGeometry(1.013, 96, 96),
    new THREE.ShaderMaterial({ vertexShader: SPHERE_VERT, fragmentShader: CLOUD_FRAG, uniforms: { uTime: uniforms.uTime, uSun: uniforms.uSun }, transparent: true, depthWrite: false }),
  );
  earth.add(clouds);

  // A faint latitude and longitude grid, like a holographic overlay on the planet.
  const grid: number[] = [];
  const R = 1.006;
  for (let lat = -60; lat <= 60; lat += 30) {
    for (let i = 0; i < 96; i++) {
      const a = latLon(lat, (i / 96) * 360).multiplyScalar(R);
      const b = latLon(lat, ((i + 1) / 96) * 360).multiplyScalar(R);
      grid.push(a.x, a.y, a.z, b.x, b.y, b.z);
    }
  }
  for (let lon = 0; lon < 360; lon += 30) {
    for (let i = -48; i < 48; i++) {
      const a = latLon((i / 48) * 90, lon).multiplyScalar(R);
      const b = latLon(((i + 1) / 48) * 90, lon).multiplyScalar(R);
      grid.push(a.x, a.y, a.z, b.x, b.y, b.z);
    }
  }
  const gridGeo = new THREE.BufferGeometry();
  gridGeo.setAttribute("position", new THREE.Float32BufferAttribute(grid, 3));
  earth.add(new THREE.LineSegments(gridGeo, new THREE.LineBasicMaterial({ color: 0x9fb7ff, transparent: true, opacity: 0.09, blending: THREE.AdditiveBlending, depthWrite: false })));

  scene.add(
    new THREE.Mesh(
      new THREE.SphereGeometry(1.15, 64, 64),
      new THREE.ShaderMaterial({ vertexShader: ATMO_VERT, fragmentShader: ATMO_FRAG, uniforms: { uSun: uniforms.uSun }, blending: THREE.AdditiveBlending, side: THREE.BackSide, transparent: true, depthWrite: false }),
    ),
  );

  const moonPivot = new THREE.Object3D();
  moonPivot.rotation.set(THREE.MathUtils.degToRad(5), 0, THREE.MathUtils.degToRad(-8));
  scene.add(moonPivot);
  const moon = new THREE.Mesh(new THREE.SphereGeometry(0.27, 96, 96), new THREE.ShaderMaterial({ vertexShader: SPHERE_VERT, fragmentShader: MOON_FRAG, uniforms: { uSun: uniforms.uSun, uRot: { value: moonRot } } }));
  moon.position.x = 2.2;
  moonPivot.add(moon);

  const glowTexture = (() => {
    const c = document.createElement("canvas");
    c.width = c.height = 64;
    const g = c.getContext("2d")!;
    const grad = g.createRadialGradient(32, 32, 0, 32, 32, 32);
    grad.addColorStop(0, "rgba(255,255,255,1)");
    grad.addColorStop(0.25, "rgba(255,255,255,0.55)");
    grad.addColorStop(1, "rgba(255,255,255,0)");
    g.fillStyle = grad;
    g.fillRect(0, 0, 64, 64);
    return new THREE.CanvasTexture(c);
  })();

  const ring = (radius: number, color: number, opacity: number) => {
    const pts = Array.from({ length: 193 }, (_, i) => {
      const a = (i / 192) * Math.PI * 2;
      return new THREE.Vector3(Math.cos(a) * radius, 0, Math.sin(a) * radius);
    });
    return new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), new THREE.LineBasicMaterial({ color, transparent: true, opacity }));
  };
  moonPivot.add(ring(2.2, 0xb8a6e8, 0.2));

  // Ground stations: a pulsing ring on the surface that turns with the planet.
  const stationPings: { ring: THREE.Mesh; dot: THREE.Sprite; phase: number; dir: THREE.Vector3 }[] = [];
  STATIONS.forEach(([lat, lon], i) => {
    const dir = latLon(lat, lon);
    const rg = new THREE.Mesh(new THREE.RingGeometry(0.9, 1, 40), new THREE.MeshBasicMaterial({ color: 0x7fe0ff, transparent: true, opacity: 0.8, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false }));
    rg.position.copy(dir).multiplyScalar(1.006);
    rg.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), dir);
    earth.add(rg);
    const dot = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTexture, color: 0x7fe0ff, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false }));
    dot.position.copy(dir).multiplyScalar(1.01);
    dot.scale.setScalar(0.05);
    earth.add(dot);
    stationPings.push({ ring: rg, dot, phase: i * 0.37, dir });
  });

  // Radar sweep around the Earth, in a tilted plane.
  const sweepUniforms = { uTime: uniforms.uTime, uR: { value: 2.5 } };
  const sweep = new THREE.Mesh(new THREE.CircleGeometry(2.5, 96), new THREE.ShaderMaterial({ vertexShader: SWEEP_VERT, fragmentShader: SWEEP_FRAG, uniforms: sweepUniforms, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide }));
  sweep.rotation.set(-Math.PI / 2 + 0.22, 0, 0.1);
  scene.add(sweep);

  const light = new THREE.DirectionalLight(0xffffff, 2.4);
  light.position.copy(sun).multiplyScalar(10);
  scene.add(light);

  /* ----- craft: orbit, glow, fading trail and a comms beam to a visible ground station ----- */
  const craftGroup = new THREE.Group();
  scene.add(craftGroup);
  const beams = new THREE.Group();
  scene.add(beams);
  interface Orbiter {
    pivot: THREE.Object3D;
    body: THREE.Mesh;
    beam: THREE.Line;
    radius: number;
    speed: number;
    phase: number;
  }
  const orbiters: Orbiter[] = [];
  const hues = [0xf5f4fa, 0x8fd6b0, 0xf0c674, 0x9fb7ff, 0xef8a9a, 0xb8a6e8, 0x7fe0ff, 0xffd9b0];

  const disposeTree = (root: THREE.Object3D) => {
    root.traverse((o) => {
      if (o instanceof THREE.Mesh || o instanceof THREE.Line) {
        o.geometry.dispose();
        (Array.isArray(o.material) ? o.material : [o.material]).forEach((m) => m.dispose());
      }
      if (o instanceof THREE.Sprite) o.material.dispose();
    });
  };
  const clearCraft = () => {
    for (const child of [...craftGroup.children, ...beams.children]) {
      child.parent?.remove(child);
      disposeTree(child);
    }
    orbiters.length = 0;
  };

  const setCraft = (count: number) => {
    clearCraft();
    const n = Math.max(1, Math.min(8, Math.round(count)));
    for (let i = 0; i < n; i++) {
      const radius = 1.28 + (i % 4) * 0.12;
      const color = hues[i % hues.length];
      const pivot = new THREE.Object3D();
      // A spread of inclinations, so the orbits cross like real ones do.
      pivot.rotation.set(THREE.MathUtils.degToRad(((i * 37) % 70) - 20), THREE.MathUtils.degToRad(i * 51), THREE.MathUtils.degToRad(30 + ((i * 29) % 60)));
      pivot.add(ring(radius, color, i === 0 ? 0.30 : 0.18));

      // Trail: an arc behind the craft that fades to nothing. It is fixed in the pivot's frame, which turns with the craft.
      const steps = 48;
      const pts: number[] = [];
      const cols: number[] = [];
      const c = new THREE.Color(color);
      for (let k = 0; k <= steps; k++) {
        const phi = (k / steps) * 1.15;
        pts.push(Math.cos(phi) * radius, 0, -Math.sin(phi) * radius);
        const f = 1 - k / steps;
        cols.push(c.r * f, c.g * f, c.b * f);
      }
      const tg = new THREE.BufferGeometry();
      tg.setAttribute("position", new THREE.Float32BufferAttribute(pts, 3));
      tg.setAttribute("color", new THREE.Float32BufferAttribute(cols, 3));
      pivot.add(new THREE.Line(tg, new THREE.LineBasicMaterial({ vertexColors: true, blending: THREE.AdditiveBlending, transparent: true, depthWrite: false })));

      const body = new THREE.Mesh(new THREE.SphereGeometry(0.03, 12, 12), new THREE.MeshBasicMaterial({ color }));
      body.position.x = radius;
      const glow = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTexture, color, transparent: true, opacity: 0.9, depthWrite: false, blending: THREE.AdditiveBlending }));
      glow.scale.setScalar(0.22);
      body.add(glow);
      pivot.add(body);
      craftGroup.add(pivot);

      const bg = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]);
      const beam = new THREE.Line(bg, new THREE.LineBasicMaterial({ color: 0x7fe0ff, transparent: true, opacity: 0.5, blending: THREE.AdditiveBlending, depthWrite: false }));
      beam.frustumCulled = false;
      beam.visible = false;
      beams.add(beam);
      orbiters.push({ pivot, body, beam, radius, speed: 0.3 + (i % 3) * 0.08 + i * 0.02, phase: i * 1.3 });
    }
  };
  setCraft(1);

  /* ----- sizing and animation ----- */
  const resize = () => {
    const w = container.clientWidth || 1;
    const h = container.clientHeight || 1;
    renderer.setSize(w, h, false);
    camera.aspect = w / h;
    // Fit the whole Moon orbit across the width, and the Earth into the space between the top stats and the bottom bar.
    const halfTan = Math.tan(THREE.MathUtils.degToRad(camera.fov / 2));
    const freeH = Math.max(h * 0.62, h - 300);
    const zWide = 2.62 / (halfTan * camera.aspect);
    const zTall = (3.4 / (2 * halfTan)) * (h / freeH);
    baseZ = Math.max(4.6, zWide, zTall);
    camera.updateProjectionMatrix();
  };
  let baseZ = 5.2;
  const observer = new ResizeObserver(() => {
    resize();
    if (store.get().settings.reducedMotion) draw(8);
  });
  observer.observe(container);
  resize();

  const pointer = new THREE.Vector2();
  const onPointer = (e: PointerEvent) => pointer.set((e.clientX / window.innerWidth) * 2 - 1, -((e.clientY / window.innerHeight) * 2 - 1));
  window.addEventListener("pointermove", onPointer, { passive: true });

  const tmpA = new THREE.Vector3();
  const tmpB = new THREE.Vector3();
  const tmpC = new THREE.Vector3();

  const draw = (t: number) => {
    uniforms.uTime.value = t;
    earth.rotation.y = t * 0.05;
    moonPivot.rotation.y = -t * 0.018;
    for (const o of orbiters) o.pivot.rotation.y = o.phase - t * o.speed;

    // A slow drift and pointer parallax make the view feel alive without ever hiding the Moon's orbit.
    camera.position.x += (Math.sin(t * 0.07) * 0.28 + pointer.x * 0.35 - camera.position.x) * 0.04;
    camera.position.y += (0.5 + Math.cos(t * 0.05) * 0.1 + pointer.y * 0.22 - camera.position.y) * 0.04;
    camera.position.z = baseZ;
    camera.lookAt(0, 0, 0);

    scene.updateMatrixWorld(true);
    earthRot.setFromMatrix4(earth.matrixWorld);
    moonRot.setFromMatrix4(moon.matrixWorld);

    // Station pulses.
    for (const s of stationPings) {
      const k = (t * 0.5 + s.phase) % 1;
      s.ring.scale.setScalar(0.012 + k * 0.05);
      (s.ring.material as THREE.MeshBasicMaterial).opacity = (1 - k) * 0.8;
      s.dot.scale.setScalar(0.045 + Math.sin(t * 3 + s.phase * 9) * 0.008);
    }

    // Comms beams: each craft links to the best ground station above its horizon.
    for (const o of orbiters) {
      o.body.getWorldPosition(tmpA);
      const cDir = tmpB.copy(tmpA).normalize();
      let best = -1;
      let bestDot = 1 / o.radius;
      stationPings.forEach((s, idx) => {
        s.dot.getWorldPosition(tmpC);
        const sd = tmpC.clone().normalize();
        const d = sd.dot(cDir);
        // The station must be above the craft's horizon and on the side of the planet facing the camera.
        if (d > bestDot && sd.dot(camera.position.clone().normalize()) > 0.05) {
          best = idx;
          bestDot = d;
        }
      });
      if (best < 0) {
        o.beam.visible = false;
        continue;
      }
      stationPings[best].dot.getWorldPosition(tmpC);
      const attr = o.beam.geometry.attributes.position as THREE.BufferAttribute;
      attr.setXYZ(0, tmpA.x, tmpA.y, tmpA.z);
      attr.setXYZ(1, tmpC.x, tmpC.y, tmpC.z);
      attr.needsUpdate = true;
      o.beam.visible = true;
      (o.beam.material as THREE.LineBasicMaterial).opacity = 0.35 + 0.25 * Math.sin(t * 6 + o.phase);
    }
    renderer.render(scene, camera);
  };

  let raf = 0;
  const start = performance.now();
  const loop = () => {
    draw((performance.now() - start) / 1000);
    raf = requestAnimationFrame(loop);
  };
  if (store.get().settings.reducedMotion) draw(8);
  else loop();

  return {
    setCraft(count: number) {
      setCraft(count);
      if (store.get().settings.reducedMotion) draw(8);
    },
    dispose() {
      cancelAnimationFrame(raf);
      observer.disconnect();
      window.removeEventListener("pointermove", onPointer);
      clearCraft();
      scene.traverse((o) => {
        if (o instanceof THREE.Mesh || o instanceof THREE.Line || o instanceof THREE.LineSegments) {
          o.geometry.dispose();
          (Array.isArray(o.material) ? o.material : [o.material]).forEach((m) => m.dispose());
        }
        if (o instanceof THREE.Sprite) o.material.dispose();
      });
      glowTexture.dispose();
      renderer.dispose();
      canvas.remove();
    },
  };
}
